-- بوابة أَثَر — «مِعيار — من أَثَر» م4-أ «بنك المهام الإنتاجية» (صوتك وقلمك) — 2027-01-08
-- نوعا بند جديدان writing_task/speaking_task · عمود task · سُلّم التقدير miaar_rubric_bands (48) · 78 مهمة (in_review)
-- · مخطّطان نظاميان مسودّة SYS-FULL/SYS-PRODUCTIVE (يُفعَّلان في م4-ب حين يدعمهما المحرّك). آمن لإعادة التنفيذ.

-- 1) النوعان الجديدان + عمود المهمة
alter table public.question_bank_items drop constraint if exists question_bank_items_item_type_check;
alter table public.question_bank_items add constraint question_bank_items_item_type_check check (item_type in ('mcq','picture_choice','picture_label','picture_sequence','true_false_notgiven','cloze_bank','matching','ordering','word_tap','short_dictation','writing_task','speaking_task'));
alter table public.question_bank_items add column if not exists task jsonb;
create index if not exists question_bank_items_productive_idx on public.question_bank_items(skill, status) where skill in ('writing','speaking');

-- 2) سُلّم التقدير (درجات 0–5 نسبية إلى مستوى المهمة؛ أربعة أبعاد لكل مهارة)
create table if not exists public.miaar_rubric_bands (
  skill text not null check (skill in ('writing','speaking')), dimension text not null, score smallint not null check (score between 0 and 5),
  dimension_ar text not null, dimension_en text not null, text_ar text not null, text_en text not null, sort int not null default 0,
  primary key (skill, dimension, score));
alter table public.miaar_rubric_bands enable row level security;
drop policy if exists miaar_rubric_bands_read on public.miaar_rubric_bands;
create policy miaar_rubric_bands_read on public.miaar_rubric_bands for select to authenticated using (true);
on conflict (skill, dimension, score) do update set dimension_ar = excluded.dimension_ar, dimension_en = excluded.dimension_en, text_ar = excluded.text_ar, text_en = excluded.text_en, sort = excluded.sort;

-- 3) 78 مهمة إنتاجية (6 كتابة + 6 تحدّث لكل مستوى A1–C2، و3+3 لما قبل A1) — in_review حتى يعتمدها إنسان
on conflict (content_version, item_code) do update set question_text = excluded.question_text, descriptor_code = excluded.descriptor_code, domain = excluded.domain, task = excluded.task, media_path = excluded.media_path, media_alt = excluded.media_alt, stimulus = excluded.stimulus, item_type = excluded.item_type, updated_at = now();

-- 4) مخطّطان نظاميان (مسودّة — لا يظهران للمتقدّم حتى م4-ب)
on conflict (code) do update set requirements = excluded.requirements, description_ar = excluded.description_ar, name_ar = excluded.name_ar, name_en = excluded.name_en, duration_minutes = excluded.duration_minutes;

-- 5) تشخيص (المتوقّع): rubric_bands = 48 · tasks_m4a = 78 · writing = 39 · speaking = 39 · in_review = 78 · blueprints_draft = 2 · descriptors_covered = 42
select (select count(*) from public.miaar_rubric_bands) as rubric_bands,
       (select count(*) from public.question_bank_items where content_version = 'athar-m4a') as tasks_m4a,
       (select count(*) from public.question_bank_items where content_version = 'athar-m4a' and skill = 'writing') as writing,
       (select count(*) from public.question_bank_items where content_version = 'athar-m4a' and skill = 'speaking') as speaking,
       (select count(*) from public.question_bank_items where content_version = 'athar-m4a' and status = 'in_review') as in_review,
       (select count(*) from public.question_bank_blueprints where code in ('SYS-FULL','SYS-PRODUCTIVE') and status = 'draft') as blueprints_draft,
       (select count(distinct descriptor_code) from public.question_bank_items where content_version = 'athar-m4a') as descriptors_covered;
