('AR-WR-A1-001', 'athar-m4a', 'A1', 'writing', 'اكتب عن نفسك: اسمك، بلدك، عملك أو دراستك، وشيئًا تحبّه.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A1-01', 'personal', '{"genre": "self_intro", "prompt_en": "Write about yourself: name, country, job or studies, and something you like.", "tips_ar": ["جمل قصيرة: أنا… أسكن في…", "استعمل «و» للربط", "من 20 إلى 40 كلمة"], "sample_ar": "اسمي ليلى. أنا من المغرب وأسكن في الرباط. أنا طالبة في الجامعة. أحبّ القراءة والشاي.", "min_words": 20, "max_words": 40, "time_seconds": 480}'::jsonb, null, null, null),
('AR-WR-A1-002', 'athar-m4a', 'A1', 'writing', 'اكتب عن عائلتك: كم شخصًا في بيتك، ومن هم، وماذا يعملون.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A1-01', 'personal', '{"genre": "self_intro", "prompt_en": "Write about your family: how many people, who they are, what they do.", "tips_ar": ["أبي… أمّي… أخي…", "استعمل الأعداد", "لا تنسَ العمل أو الدراسة"], "sample_ar": "في بيتي خمسة أشخاص: أبي وأمّي وأخي وأختي وأنا. أبي مهندس وأمّي معلّمة. أخي طالب في المدرسة.", "min_words": 20, "max_words": 40, "time_seconds": 480}'::jsonb, '/miaar/img/family.svg', 'family', '{"image": "/miaar/img/family.svg", "alt": "family"}'::jsonb),
('AR-WR-A1-003', 'athar-m4a', 'A1', 'writing', 'سجّلت في نادٍ رياضي. املأ النموذج بجمل قصيرة: الاسم الكامل · العمر · الجنسية · رقم الهاتف · الرياضة التي تريدها ولماذا.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A1-02', 'public', '{"genre": "form", "prompt_en": "Fill in a sports-club form in short sentences.", "tips_ar": ["اكتب كل معلومة في سطر", "«أريد السباحة لأنّ…»", "يمكنك استعمال أرقام"], "sample_ar": "الاسم: عمر خالد. العمر: 25 سنة. الجنسية: أردني. الهاتف: 0501234567. أريد السباحة لأنّها ممتعة.", "min_words": 20, "max_words": 40, "time_seconds": 480}'::jsonb, null, null, null),
('AR-WR-A1-004', 'athar-m4a', 'A1', 'writing', 'تريد الالتحاق بدورة لغة. اكتب طلبًا قصيرًا: من أنت، ما لغتك الأم، ولماذا تتعلّم العربية.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A1-02', 'educational', '{"genre": "form", "prompt_en": "Write a short course application: who you are, your first language, why you learn Arabic.", "tips_ar": ["ثلاث جمل كافية", "«أتعلّم العربية لأنّ…»", "ابدأ بـ«أنا»"], "sample_ar": "أنا ماريا من إسبانيا. لغتي الأم الإسبانية. أتعلّم العربية لأنّي أعمل في دبي وأحبّ الثقافة العربية.", "min_words": 20, "max_words": 40, "time_seconds": 480}'::jsonb, null, null, null),
('AR-WR-A1-005', 'athar-m4a', 'A1', 'writing', 'صديقك ينجح في الامتحان. اكتب له بطاقة تهنئة قصيرة.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A1-03', 'personal', '{"genre": "card", "prompt_en": "Write a short congratulations card to a friend who passed an exam.", "tips_ar": ["ابدأ بالاسم: «عزيزي…»", "كلمة تهنئة ودعاء", "اختم باسمك"], "sample_ar": "عزيزي سامي، مبروك النجاح! أنا سعيد جدًّا. إلى الأمام دائمًا. صديقك، كريم.", "min_words": 20, "max_words": 40, "time_seconds": 480}'::jsonb, '/miaar/img/gift.svg', 'gift', '{"image": "/miaar/img/gift.svg", "alt": "gift"}'::jsonb),
('AR-WR-A1-006', 'athar-m4a', 'A1', 'writing', 'اكتب رسالة قصيرة جدًّا إلى زميلك: أنت مريض اليوم ولن تأتي إلى الدرس، واطلب منه الواجب.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A1-03', 'personal', '{"genre": "message", "prompt_en": "Write a very short message to a classmate: you are sick, will miss class, ask for the homework.", "tips_ar": ["«مرحبًا…»", "سبب واحد وطلب واحد", "اختم بـ«شكرًا»"], "sample_ar": "مرحبًا نور، أنا مريض اليوم ولن آتي إلى الدرس. من فضلك أرسلي لي الواجب. شكرًا!", "min_words": 20, "max_words": 40, "time_seconds": 480}'::jsonb, null, null, null),
('AR-SP-A1-001', 'athar-m4a', 'A1', 'speaking', 'عرّف بنفسك في 30 ثانية: اسمك، بلدك، أين تسكن، ماذا تعمل أو تدرس.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A1-01', 'personal', '{"genre": "self_intro", "prompt_en": "Introduce yourself in 30 seconds.", "tips_ar": ["اسمي… أنا من…", "تكلّم ببطء ووضوح", "ثلاث أو أربع جمل"], "sample_ar": "اسمي حسن. أنا من السودان وأسكن في جدة. أنا محاسب وأحبّ كرة القدم.", "min_seconds": 10, "max_seconds": 45, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-A1-002', 'athar-m4a', 'A1', 'speaking', 'تخيّل أنّك تقابل شخصًا جديدًا. اسأله ثلاثة أسئلة: عن اسمه، وبلده، وعمله.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A1-01', 'personal', '{"genre": "questions", "prompt_en": "Ask a new acquaintance three questions: name, country, job.", "tips_ar": ["ما اسمك؟", "من أين أنت؟", "ماذا تعمل؟"], "sample_ar": "مرحبًا! ما اسمك؟ من أين أنت؟ ماذا تعمل؟", "min_seconds": 10, "max_seconds": 45, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-A1-003', 'athar-m4a', 'A1', 'speaking', 'أنت في مقهى. اطلب مشروبًا وشيئًا للأكل، ثم اشكر العامل.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A1-02', 'public', '{"genre": "request", "prompt_en": "In a café: order a drink and something to eat, then thank the waiter.", "tips_ar": ["«من فضلك…»", "اذكر شيئين", "اختم بـ«شكرًا»"], "sample_ar": "من فضلك، أريد قهوة وكعكة. كم الحساب؟ شكرًا جزيلًا.", "min_seconds": 10, "max_seconds": 45, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/coffee.svg', 'coffee', '{"image": "/miaar/img/coffee.svg", "alt": "coffee"}'::jsonb),
('AR-SP-A1-004', 'athar-m4a', 'A1', 'speaking', 'أنت في متجر وتريد شراء قميص. اسأل عن السعر واللون، ثم اشكر البائع.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A1-02', 'public', '{"genre": "request", "prompt_en": "In a shop: ask the price and colour of a shirt, then thank the seller.", "tips_ar": ["كم سعر…؟", "هل عندك اللون…؟", "جملتان أو ثلاث"], "sample_ar": "لو سمحت، كم سعر هذا القميص؟ هل عندك اللون الأزرق؟ شكرًا.", "min_seconds": 10, "max_seconds": 45, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/shirt.svg', 'shirt', '{"image": "/miaar/img/shirt.svg", "alt": "shirt"}'::jsonb),
('AR-SP-A1-005', 'athar-m4a', 'A1', 'speaking', 'أجب عن هذه الأسئلة بصوتك: ما هو يومك المفضّل؟ ماذا تأكل في الفطور؟ متى تنام؟', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A1-03', 'personal', '{"genre": "answer", "prompt_en": "Answer: favourite day? breakfast? bedtime?", "tips_ar": ["أجب عن كل سؤال بجملة", "يومي المفضّل هو…", "لا تنسَ الساعة"], "sample_ar": "يومي المفضّل هو الجمعة. آكل في الفطور خبزًا وجبنًا. أنام في الساعة الحادية عشرة.", "min_seconds": 10, "max_seconds": 45, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-A1-006', 'athar-m4a', 'A1', 'speaking', 'أجب: أين تسكن؟ كم غرفة في بيتك؟ ما الشيء الذي تحبّه في بيتك؟', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A1-03', 'personal', '{"genre": "answer", "prompt_en": "Answer: where do you live? how many rooms? what do you like about your home?", "tips_ar": ["أسكن في…", "في بيتي… غرف", "أحبّ… لأنّ…"], "sample_ar": "أسكن في شقّة في الرياض. في بيتي ثلاث غرف. أحبّ المطبخ لأنّه كبير.", "min_seconds": 10, "max_seconds": 45, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/house.svg', 'house', '{"image": "/miaar/img/house.svg", "alt": "house"}'::jsonb),
('AR-WR-A2-001', 'athar-m4a', 'A2', 'writing', 'اكتب رسالة إلى صديق تصف فيها يومك أمس: ماذا فعلت في الصباح والمساء، ومع من، وكيف كان شعورك.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A2-01', 'personal', '{"genre": "message", "prompt_en": "Write a message to a friend describing your day yesterday.", "tips_ar": ["استعمل الفعل الماضي", "الصباح ثم المساء", "جملة عن شعورك"], "sample_ar": "مرحبًا سلمى، أمس كان يومًا جميلًا. في الصباح ذهبت إلى السوق مع أمّي واشترينا فواكه. في المساء زرنا جدّتي وأكلنا معها. كنت سعيدة جدًّا. إلى اللقاء، هدى.", "min_words": 40, "max_words": 70, "time_seconds": 600}'::jsonb, null, null, null),
('AR-WR-A2-002', 'athar-m4a', 'A2', 'writing', 'اكتب في مذكّراتك عن عطلة نهاية الأسبوع الماضية: أين ذهبت، وماذا فعلت، وما أحببته أكثر.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A2-01', 'personal', '{"genre": "diary", "prompt_en": "Diary entry about last weekend.", "tips_ar": ["ثلاث فقرات قصيرة", "استعمل «ثم» و«بعد ذلك»", "اختم بما أحببته"], "sample_ar": "في عطلة الأسبوع ذهبت مع أصدقائي إلى البحر. سبحنا ولعبنا الكرة، ثم أكلنا سمكًا في مطعم صغير. بعد ذلك رجعنا متأخّرين. أحببت غروب الشمس أكثر شيء.", "min_words": 40, "max_words": 70, "time_seconds": 600}'::jsonb, '/miaar/img/sea.svg', 'sea', '{"image": "/miaar/img/sea.svg", "alt": "sea"}'::jsonb),
('AR-WR-A2-003', 'athar-m4a', 'A2', 'writing', 'صف شخصًا تحبّه (قريبًا أو صديقًا): شكله، وصفاته، وماذا يعمل، ولماذا تحبّه.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A2-02', 'personal', '{"genre": "description", "prompt_en": "Describe someone you love: looks, character, job, why you love them.", "tips_ar": ["اربط بـ«و» و«لكن» و«لأنّ»", "صفتان على الأقل", "جملة ختامية"], "sample_ar": "جدّي رجل طويل وشعره أبيض. هو هادئ وكريم، ويحبّ الأطفال. كان معلّمًا في المدرسة، لكنّه الآن في البيت. أحبّه لأنّه يحكي لي قصصًا جميلة.", "min_words": 40, "max_words": 70, "time_seconds": 600}'::jsonb, '/miaar/img/oldman.svg', 'oldman', '{"image": "/miaar/img/oldman.svg", "alt": "oldman"}'::jsonb),
('AR-WR-A2-004', 'athar-m4a', 'A2', 'writing', 'صف مكانًا تحبّ زيارته في مدينتك: أين هو، ماذا يوجد فيه، ومتى تذهب إليه ومع من.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A2-02', 'public', '{"genre": "description", "prompt_en": "Describe a place you like visiting in your city.", "tips_ar": ["ابدأ بالمكان واسمه", "ماذا ترى وماذا تفعل", "متى ومع من"], "sample_ar": "أحبّ حديقة الملك فهد في وسط المدينة. فيها أشجار كثيرة وبحيرة صغيرة وملعب للأطفال. أذهب إليها يوم الجمعة مع عائلتي، ثم نشرب الشاي هناك.", "min_words": 40, "max_words": 70, "time_seconds": 600}'::jsonb, null, null, null),
('AR-WR-A2-005', 'athar-m4a', 'A2', 'writing', 'اكتب ملاحظة قصيرة لمديرك: تطلب إجازة يومًا واحدًا، مع ذكر السبب والتاريخ، وتقترح من يقوم بعملك.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A2-03', 'professional', '{"genre": "note", "prompt_en": "Short note to your manager asking for one day off.", "tips_ar": ["«الأستاذ الفاضل…»", "السبب والتاريخ", "اقتراح بديل"], "sample_ar": "الأستاذ الفاضل أحمد، أرجو الموافقة على إجازة يوم الثلاثاء القادم بسبب موعد في المستشفى. سيقوم زميلي خالد بعملي في ذلك اليوم. شكرًا لتفهّمك. سعاد.", "min_words": 40, "max_words": 70, "time_seconds": 600}'::jsonb, null, null, null),
('AR-WR-A2-006', 'athar-m4a', 'A2', 'writing', 'اكتب رسالة قصيرة إلى صاحب الشقّة: المكيّف لا يعمل، اشرح المشكلة، واطلب إصلاحه، واقترح وقتًا مناسبًا.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-A2-03', 'public', '{"genre": "request", "prompt_en": "Short message to your landlord: the AC is broken.", "tips_ar": ["المشكلة في جملة", "الطلب بأدب", "وقت مناسب"], "sample_ar": "السلام عليكم أستاذ سعيد، المكيّف في غرفة النوم لا يعمل منذ يومين والجوّ حارّ جدًّا. هل يمكن إرسال فنّي لإصلاحه؟ أنا في البيت بعد الساعة الخامسة مساءً. شكرًا.", "min_words": 40, "max_words": 70, "time_seconds": 600}'::jsonb, null, null, null),
('AR-SP-A2-001', 'athar-m4a', 'A2', 'speaking', 'تحدّث عن يومك العادي: متى تستيقظ، ماذا تفعل في العمل أو الدراسة، وماذا تفعل في المساء.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A2-01', 'personal', '{"genre": "routine", "prompt_en": "Talk about your typical day.", "tips_ar": ["رتّب من الصباح إلى المساء", "استعمل «عادةً» و«أحيانًا»", "45 ثانية تقريبًا"], "sample_ar": "أستيقظ عادةً في السادسة وأصلّي ثم أفطر. أذهب إلى العمل في السابعة والنصف، وأعمل في مكتب حتى الرابعة. في المساء أزور أصدقائي أحيانًا أو أقرأ.", "min_seconds": 15, "max_seconds": 60, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-A2-002', 'athar-m4a', 'A2', 'speaking', 'تحدّث عن عائلتك وعملك: من يعيش معك، وماذا يعمل كل واحد، وماذا تحبّون أن تفعلوا معًا.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A2-01', 'personal', '{"genre": "family", "prompt_en": "Talk about your family and work.", "tips_ar": ["أفراد العائلة", "العمل أو الدراسة", "نشاط مشترك"], "sample_ar": "أعيش مع زوجتي وطفلينا. زوجتي طبيبة وأنا أعمل في بنك. في العطلة نحبّ أن نذهب إلى الحديقة أو نطبخ معًا.", "min_seconds": 15, "max_seconds": 60, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/family.svg', 'family', '{"image": "/miaar/img/family.svg", "alt": "family"}'::jsonb),
('AR-SP-A2-003', 'athar-m4a', 'A2', 'speaking', 'أنت في الصيدلية. اشرح للصيدلي أنّ عندك صداعًا وحرارة منذ أمس، واسأل عن دواء وكيف تأخذه.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A2-02', 'public', '{"genre": "service", "prompt_en": "At the pharmacy: explain symptoms and ask about medicine.", "tips_ar": ["الأعراض ومنذ متى", "اسأل عن الدواء", "اسأل: كم مرّة في اليوم؟"], "sample_ar": "السلام عليكم. عندي صداع وحرارة منذ أمس. هل عندكم دواء مناسب؟ كم مرّة آخذه في اليوم؟ وهل آخذه بعد الأكل؟", "min_seconds": 15, "max_seconds": 60, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/medicine.svg', 'medicine', '{"image": "/miaar/img/medicine.svg", "alt": "medicine"}'::jsonb),
('AR-SP-A2-004', 'athar-m4a', 'A2', 'speaking', 'اتّصل بمطعم لحجز طاولة: عدد الأشخاص، اليوم والساعة، واسأل عن مكان للسيارة.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A2-02', 'public', '{"genre": "service", "prompt_en": "Phone a restaurant to book a table.", "tips_ar": ["كم شخصًا", "اليوم والساعة", "سؤال إضافي"], "sample_ar": "مرحبًا، أريد حجز طاولة لأربعة أشخاص يوم الخميس الساعة الثامنة مساءً. هل عندكم موقف للسيارات؟ شكرًا.", "min_seconds": 15, "max_seconds": 60, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/restaurant.svg', 'restaurant', '{"image": "/miaar/img/restaurant.svg", "alt": "restaurant"}'::jsonb),
('AR-SP-A2-005', 'athar-m4a', 'A2', 'speaking', 'ما خططك للعطلة القادمة؟ أين ستذهب، مع من، وماذا ستفعل هناك؟', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A2-03', 'personal', '{"genre": "plans", "prompt_en": "Talk about your plans for the next holiday.", "tips_ar": ["استعمل «سـ» و«سوف»", "المكان والأشخاص", "نشاطان على الأقل"], "sample_ar": "في العطلة القادمة سأسافر إلى تركيا مع أختي. سنزور إسطنبول ونركب السفينة في البوسفور، وسوف نتذوّق الحلويات التركية.", "min_seconds": 15, "max_seconds": 60, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/airplane.svg', 'airplane', '{"image": "/miaar/img/airplane.svg", "alt": "airplane"}'::jsonb),
('AR-SP-A2-006', 'athar-m4a', 'A2', 'speaking', 'لديك أسبوع مزدحم في العمل أو الدراسة. تحدّث عن مواعيدك وترتيباتك: ماذا ستفعل كل يوم؟', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-A2-03', 'professional', '{"genre": "plans", "prompt_en": "Describe your busy week ahead.", "tips_ar": ["اذكر ثلاثة أيام", "استعمل الأوقات", "رتّب بالتتابع"], "sample_ar": "يوم الأحد عندي اجتماع في الصباح. يوم الثلاثاء سأقدّم عرضًا للمدير. ويوم الخميس سأسافر إلى الدمام لزيارة العملاء ثم أرجع مساءً.", "min_seconds": 15, "max_seconds": 60, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/calendar.svg', 'calendar', '{"image": "/miaar/img/calendar.svg", "alt": "calendar"}'::jsonb),
('AR-WR-B1-001', 'athar-m4a', 'B1', 'writing', 'اكتب مقالًا قصيرًا لمجلّة المعهد بعنوان «لماذا أتعلّم العربية؟»: أسبابك، والصعوبات التي تواجهها، وكيف تتغلّب عليها.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B1-01', 'educational', '{"genre": "article", "prompt_en": "Short article: Why I learn Arabic — reasons, difficulties, solutions.", "tips_ar": ["مقدّمة وثلاث فقرات وخاتمة", "روابط: «أولًا» «بالإضافة إلى» «لذلك»", "80–130 كلمة"], "sample_ar": "بدأت تعلّم العربية قبل سنتين لأسباب عدّة: أوّلها العمل، فأنا أتعامل مع زبائن عرب يوميًّا، وثانيها حبّي للقرآن الكريم. بالإضافة إلى ذلك أحبّ الأفلام العربية. أمّا الصعوبات فأهمّها الإعراب والفرق بين الفصحى والعامية. لذلك أقرأ كل يوم عشر دقائق وأشاهد الأخبار بالعربية. وبفضل ذلك أصبحت أفهم أكثر، وأشعر أنّ العربية لم تعد غريبة عنّي.", "min_words": 80, "max_words": 130, "time_seconds": 720}'::jsonb, null, null, null),
('AR-WR-B1-002', 'athar-m4a', 'B1', 'writing', 'اكتب تدوينة عن مدينة زرتها مؤخّرًا: ما الذي أعجبك، وما الذي لم يعجبك، ونصيحة لمن يريد زيارتها.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B1-01', 'public', '{"genre": "blog", "prompt_en": "Blog post about a city you recently visited.", "tips_ar": ["أعجبني / لم يعجبني", "نصيحة عملية", "فقرة لكل جزء"], "sample_ar": "زرت مدينة مسقط الشهر الماضي. أعجبني هدوؤها وبحرها النظيف وكرم أهلها الذين ساعدوني في كل مكان. لكن لم تعجبني حرارة الجوّ في الظهيرة، فقد كان من الصعب المشي في الشوارع. نصيحتي لمن يريد زيارتها أن يذهب في الشتاء، وأن يزور سوق مطرح في المساء، وأن يجرّب الحلوى العمانية.", "min_words": 80, "max_words": 130, "time_seconds": 720}'::jsonb, null, null, null),
('AR-WR-B1-003', 'athar-m4a', 'B1', 'writing', 'اروِ تجربة غيّرت شيئًا في حياتك (سفر، عمل، لقاء): ماذا حدث، وكيف شعرت، وماذا تعلّمت.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B1-02', 'personal', '{"genre": "narrative", "prompt_en": "Narrate an experience that changed something in your life.", "tips_ar": ["البداية ثم الحدث ثم النتيجة", "مشاعرك بصراحة", "ما تعلّمته"], "sample_ar": "قبل ثلاث سنوات انتقلت وحدي إلى مدينة جديدة للعمل. في الأسابيع الأولى شعرت بالوحدة والخوف، ولم أكن أعرف أحدًا. ثم سجّلت في نادٍ للمشي، وهناك تعرّفت إلى أصدقاء من بلدان مختلفة. تعلّمت من تلك التجربة أنّ الخطوة الأولى صعبة لكنّها ضرورية، وأنّ الناس أطيب ممّا نتخيّل.", "min_words": 80, "max_words": 130, "time_seconds": 720}'::jsonb, null, null, null),
('AR-WR-B1-004', 'athar-m4a', 'B1', 'writing', 'صديقك يسألك: هل الأفضل أن يدرس في بلده أم في الخارج؟ اكتب له رأيك مع أسبابك، واذكر تجربة تعرفها.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B1-02', 'personal', '{"genre": "opinion", "prompt_en": "Write your opinion: study at home or abroad?", "tips_ar": ["رأيك في أوّل جملة", "سببان مع مثال", "جملة تنصحه فيها"], "sample_ar": "عزيزي عادل، في رأيي الدراسة في الخارج أفضل إذا كانت الظروف تسمح. أوّلًا لأنّك ستتعلّم لغة جديدة وتعيش ثقافة مختلفة، وثانيًا لأنّ الشهادة الأجنبية تساعد في العمل. ابن عمّي درس في ماليزيا وعاد أكثر ثقة واستقلالًا. لكن إن كان المال مشكلة فابدأ هنا وفكّر في الماجستير خارجًا. اختر ما يريحك.", "min_words": 80, "max_words": 130, "time_seconds": 720}'::jsonb, null, null, null),
('AR-WR-B1-005', 'athar-m4a', 'B1', 'writing', 'اكتب بريدًا رسميًّا إلى شركة طيران: فُقدت حقيبتك في الرحلة، اذكر تفاصيل الرحلة ووصف الحقيبة، واطلب التعويض أو إعادتها.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B1-03', 'professional', '{"genre": "formal_email", "prompt_en": "Formal email to an airline about lost luggage.", "tips_ar": ["تحية رسمية وموضوع واضح", "التفاصيل: الرقم، التاريخ، الوصف", "طلب محدّد وختام رسمي"], "sample_ar": "السادة خدمة العملاء المحترمين، تحية طيبة وبعد، سافرت على رحلتكم رقم 512 من القاهرة إلى الرياض يوم 3 مارس، ولم أجد حقيبتي عند الوصول. الحقيبة زرقاء متوسّطة الحجم وعليها بطاقة باسمي. أرجو إبلاغي بمكانها وإرسالها إلى عنواني، أو تعويضي عن محتوياتها إن فُقدت. شاكرًا تعاونكم، منى حسن، 0551234567.", "min_words": 80, "max_words": 130, "time_seconds": 720}'::jsonb, '/miaar/img/suitcase.svg', 'suitcase', '{"image": "/miaar/img/suitcase.svg", "alt": "suitcase"}'::jsonb),
('AR-WR-B1-006', 'athar-m4a', 'B1', 'writing', 'اكتب رسالة اعتذار رسمية إلى مدرّسك لأنّك لم تسلّم المشروع في موعده: السبب، وما فعلته، وموعد جديد تقترحه.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B1-03', 'public', '{"genre": "formal_email", "prompt_en": "Formal apology email to a teacher for a late project.", "tips_ar": ["اعتذار واضح في البداية", "سبب صادق دون إطالة", "موعد بديل محدّد"], "sample_ar": "الأستاذة الفاضلة نادية، أعتذر بصدق عن تأخّري في تسليم مشروع القراءة. فقد مرضت والدتي الأسبوع الماضي ورافقتها في المستشفى ثلاثة أيام. أنهيت الآن معظم العمل وبقي الجزء الأخير. هل يمكن قبول المشروع يوم الأحد القادم؟ شكرًا لتفهّمك. مع التقدير، طارق.", "min_words": 80, "max_words": 130, "time_seconds": 720}'::jsonb, null, null, null),
('AR-SP-B1-001', 'athar-m4a', 'B1', 'speaking', 'وصلت إلى الفندق ووجدت أنّ الحجز غير موجود. تحدّث مع موظّف الاستقبال: اشرح الموقف، وأعطِ التفاصيل، واقترح حلًّا.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B1-01', 'public', '{"genre": "situation", "prompt_en": "At a hotel the booking is missing: explain, give details, propose a solution.", "tips_ar": ["ابدأ بهدوء وأدب", "التفاصيل: الاسم، التاريخ، رقم الحجز", "اقترح حلًّا"], "sample_ar": "مساء الخير. حجزت غرفة باسم فريد عبد الله لثلاث ليالٍ من اليوم، وعندي رسالة التأكيد على هاتفي. أفهم أنّ الحجز غير ظاهر عندكم، لكن هل يمكن أن تتحقّقوا من البريد الإلكتروني؟ وإن لم تتوفّر الغرفة نفسها فأقبل بغرفة أخرى بالسعر نفسه.", "min_seconds": 25, "max_seconds": 75, "prep_seconds": 30, "retakes": 1}'::jsonb, '/miaar/img/hotel.svg', 'hotel', '{"image": "/miaar/img/hotel.svg", "alt": "hotel"}'::jsonb),
('AR-SP-B1-002', 'athar-m4a', 'B1', 'speaking', 'تأخّرت عن اجتماع مهمّ بسبب الازدحام. اتّصل بزميلك: اعتذر، واشرح ما حدث، واطلب منه أن يبدأ بدونك ويخبرك بما فاتك.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B1-01', 'professional', '{"genre": "situation", "prompt_en": "Phone a colleague: apologise for being late, explain, ask them to start without you.", "tips_ar": ["اعتذار ثم شرح", "طلب واضح", "اختم بوقت وصولك"], "sample_ar": "مرحبًا ريم، أعتذر جدًّا، أنا عالق في ازدحام شديد على الطريق الدائري بسبب حادث. أرجو أن تبدئي الاجتماع بدوني وتعرضي النقاط الأولى، وسأصل خلال عشرين دقيقة إن شاء الله. أخبريني بما فاتني حين أصل.", "min_seconds": 25, "max_seconds": 75, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-B1-003', 'athar-m4a', 'B1', 'speaking', 'احكِ قصّة موقف محرج أو مضحك حدث لك: ماذا حدث، وكيف تصرّفت، وماذا تعلّمت.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B1-02', 'personal', '{"genre": "narrative", "prompt_en": "Tell a story about an embarrassing or funny situation.", "tips_ar": ["الزمان والمكان أولًا", "التسلسل: ثم… وفجأة…", "الدرس المستفاد"], "sample_ar": "في أوّل يوم لي في العمل دخلت قاعة الاجتماع الخطأ وجلست عشر دقائق أستمع إلى عرض لا أفهم منه شيئًا، ثم سألني المدير عن رأيي! اعتذرت وضحك الجميع. تعلّمت أن أسأل قبل أن أدخل.", "min_seconds": 25, "max_seconds": 75, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-B1-004', 'athar-m4a', 'B1', 'speaking', 'بعض الناس يرون أنّ الهاتف المحمول ضارّ بالأطفال. ما رأيك؟ أعطِ سببين على الأقل ومثالًا من حياتك.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B1-02', 'public', '{"genre": "opinion", "prompt_en": "Opinion: are mobile phones harmful for children? Two reasons and an example.", "tips_ar": ["رأيك بوضوح", "سببان مرتّبان", "مثال واقعي"], "sample_ar": "في رأيي الهاتف ليس ضارًّا في ذاته، بل طريقة استعماله. فمن جهة يساعد الطفل على التعلّم، ومن جهة أخرى يضيّع وقته إن لم يراقبه الأهل. ابن أختي مثلًا يستعمله ساعة واحدة يوميًّا بتطبيقات تعليمية وهذا مفيد جدًّا.", "min_seconds": 25, "max_seconds": 75, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-B1-005', 'athar-m4a', 'B1', 'speaking', 'موضوع مفاجئ: «الطعام». تحدّث مباشرة دون تحضير طويل عن أكلتك المفضّلة، وكيف تُحضَّر، ولماذا تحبّها.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B1-03', 'personal', '{"genre": "spontaneous", "prompt_en": "Spontaneous talk: food — favourite dish, how it is made, why you like it.", "tips_ar": ["لا تتوقّف طويلًا", "الخطوات باختصار", "ذكرى مرتبطة بها"], "sample_ar": "أكلتي المفضّلة هي الكبسة. تُطبخ بالأرز واللحم والبهارات، وتُترك على نار هادئة حتى تتشرّب الطعم. أحبّها لأنّها تذكّرني باجتماع العائلة يوم الجمعة في بيت جدّتي.", "min_seconds": 25, "max_seconds": 75, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-B1-006', 'athar-m4a', 'B1', 'speaking', 'موضوع مفاجئ: «المدينة والقرية». أين تفضّل أن تعيش؟ تحدّث عن المزايا والعيوب من تجربتك.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B1-03', 'public', '{"genre": "spontaneous", "prompt_en": "Spontaneous talk: city or village — where would you rather live?", "tips_ar": ["اختر جانبًا", "ميزة وعيب لكل منهما", "اختم بقرارك"], "sample_ar": "أفضّل المدينة رغم ضجيجها، لأنّ فيها العمل والمستشفيات والجامعات. القرية هادئة وهواؤها نظيف، لكنّ الخدمات قليلة. لذلك أعيش في المدينة وأزور القرية في العطلات.", "min_seconds": 25, "max_seconds": 75, "prep_seconds": 30, "retakes": 1}'::jsonb, null, null, null),
('AR-WR-B2-001', 'athar-m4a', 'B2', 'writing', 'اكتب مقالًا رأييًّا: «هل ينبغي أن يكون التعليم الجامعي مجّانيًّا للجميع؟» اعرض موقفك بحجّتين مدعومتين، وناقش رأيًا مخالفًا، ثم اختم.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B2-01', 'educational', '{"genre": "essay", "prompt_en": "Opinion essay: should university be free for all?", "tips_ar": ["أطروحة واضحة في المقدّمة", "حجّتان بأدلّة أو أمثلة", "فقرة للرأي المخالف وردّه"], "sample_ar": "يرى كثيرون أنّ مجّانية التعليم الجامعي حقّ، وأنا أميل إلى هذا الرأي بشروط. فالحجّة الأولى أنّ التعليم استثمار عامّ يعود على الاقتصاد بخرّيجين منتجين، كما تشهد تجارب دول أوروبية. والثانية أنّ الرسوم تحرم الموهوبين من الأسر الفقيرة. غير أنّ المعارضين يحذّرون من إرهاق الميزانية وتراجع الجودة، وهو تحفّظ وجيه، إلا أنّ الحلّ في توجيه المجّانية إلى التخصّصات التي يحتاجها سوق العمل وربطها بالتفوّق. وخلاصة القول إنّ المجّانية المشروطة تحقّق العدالة دون التفريط في الجودة.", "min_words": 150, "max_words": 220, "time_seconds": 900}'::jsonb, null, null, null),
('AR-WR-B2-002', 'athar-m4a', 'B2', 'writing', 'اكتب تقريرًا قصيرًا لمديرك عن مشكلة تأخّر الموظّفين في الصباح: وصف المشكلة بالأرقام (افترضها)، أسبابها المحتملة، وتوصيتان عمليّتان.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B2-01', 'professional', '{"genre": "report", "prompt_en": "Short report to your manager on staff lateness with recommendations.", "tips_ar": ["عناوين فرعية: المشكلة · الأسباب · التوصيات", "أرقام تقريبية", "توصيات قابلة للتنفيذ"], "sample_ar": "الموضوع: تأخّر الحضور الصباحي. المشكلة: خلال شهر فبراير تأخّر 30% من الموظّفين أكثر من عشر دقائق ثلاث مرّات أسبوعيًّا على الأقل، ما أخّر بدء خدمة العملاء. الأسباب المحتملة: ازدحام الطريق بعد افتتاح المدرسة المجاورة، وغياب نظام دوام مرن، وضعف المتابعة. التوصيات: أوّلًا اعتماد مرونة نصف ساعة في الحضور والانصراف لمدّة تجريبية، وثانيًا ربط الالتزام بتقييم الأداء الشهري مع تنبيه ودّي قبل أيّ إجراء.", "min_words": 150, "max_words": 220, "time_seconds": 900}'::jsonb, null, null, null),
('AR-WR-B2-003', 'athar-m4a', 'B2', 'writing', 'قرأت ثلاثة آراء عن العمل عن بُعد: (أ) يرفع الإنتاجية 20% · (ب) يُضعف العلاقات بين الزملاء · (ج) يوفّر على الشركات تكاليف المكاتب لكنّه يزيد ساعات العمل غير المدفوعة. لخّصها في فقرة واحدة متوازنة دون رأيك الشخصي.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B2-02', 'educational', '{"genre": "summary", "prompt_en": "Summarise three given views on remote work in one balanced paragraph.", "tips_ar": ["لا تنقل الجمل حرفيًّا", "اربط بين المصادر", "لا رأي شخصيًّا"], "sample_ar": "تتباين الآراء حول العمل عن بُعد؛ فبينما يشير المصدر الأوّل إلى ارتفاع الإنتاجية بنحو الخمس، يحذّر الثاني من تآكل العلاقات المهنية بين الزملاء. أمّا المصدر الثالث فيقدّم صورة مركّبة: توفير ملموس في تكاليف المكاتب يقابله تمدّد ساعات العمل دون أجر. وهكذا يبدو أنّ المكاسب الاقتصادية للنموذج تتزامن مع كلفة اجتماعية وشخصية تستدعي الموازنة.", "min_words": 150, "max_words": 220, "time_seconds": 900}'::jsonb, null, null, null),
('AR-WR-B2-004', 'athar-m4a', 'B2', 'writing', 'شاهدت تقريرًا تلفزيونيًّا وقرأت مقالين عن أزمة المياه في منطقتك. اكتب ملخّصًا لصديق أجنبي لا يعرف شيئًا عن الموضوع: الأسباب، الآثار، والحلول المطروحة (افترض المحتوى).', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B2-02', 'public', '{"genre": "summary", "prompt_en": "Summarise the water crisis for a foreign friend: causes, effects, proposed solutions.", "tips_ar": ["اشرح لمن لا يعرف", "ثلاثة محاور واضحة", "تجنّب التفاصيل الزائدة"], "sample_ar": "باختصار، تعاني منطقتنا من نقص المياه لثلاثة أسباب رئيسة: قلّة الأمطار في السنوات الخمس الأخيرة، والاستهلاك الزراعي المفرط، وتسرّب الشبكات القديمة. وقد أدّى ذلك إلى تقنين المياه في بعض الأحياء وارتفاع أسعار الخضار. أمّا الحلول المطروحة فتشمل محطّات تحلية جديدة، ودعم الريّ بالتنقيط، وحملات توعية للحدّ من الهدر المنزلي، وإن كان أكثرها يحتاج سنوات ليؤتي ثماره.", "min_words": 150, "max_words": 220, "time_seconds": 900}'::jsonb, '/miaar/img/water.svg', 'water', '{"image": "/miaar/img/water.svg", "alt": "water"}'::jsonb),
('AR-WR-B2-005', 'athar-m4a', 'B2', 'writing', 'اكتب خطاب شكوى رسميًّا إلى شركة اتّصالات بعد انقطاع الإنترنت المتكرّر: السجلّ الزمني للمشكلة، تأثيرها على عملك، وما تطلبه بالضبط، بنبرة حازمة مهذّبة.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B2-03', 'professional', '{"genre": "formal_letter", "prompt_en": "Formal complaint letter to a telecom company about repeated outages.", "tips_ar": ["سجلّ الأحداث بالتواريخ", "الأثر على العمل", "طلب محدّد ومهلة"], "sample_ar": "السادة شركة الاتّصالات المحترمين، أكتب إليكم بخصوص الانقطاع المتكرّر لخدمة الإنترنت في منزلي (رقم العقد 88214). فقد انقطعت الخدمة ستّ مرّات بين 1 و15 أبريل، وبلغ مجموع الانقطاع ثلاثين ساعة، رغم ثلاث بلاغات لم تُعالج جذريًّا. وبما أنّني أعمل عن بُعد فقد تسبّب ذلك في فقدان اجتماعين مع عملاء. وعليه، أطلب إصلاحًا نهائيًّا خلال سبعة أيام، وتعويضًا عن أيام الانقطاع في فاتورة الشهر الجاري، وإلا فسأضطرّ إلى إنهاء العقد ورفع شكوى إلى هيئة الاتّصالات. وتفضّلوا بقبول فائق الاحترام، سلطان العمري.", "min_words": 150, "max_words": 220, "time_seconds": 900}'::jsonb, null, null, null),
('AR-WR-B2-006', 'athar-m4a', 'B2', 'writing', 'اكتب الرسالة نفسها مرّتين بسجلّين مختلفين: (1) إلى عميد الكلّية تطلب فيها تمديد موعد تسليم بحث التخرّج، (2) ثمّ رسالة قصيرة غير رسمية إلى زميلك تشرح فيها الطلب نفسه. أظهر الفرق في الأسلوب.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-B2-03', 'educational', '{"genre": "formal_letter", "prompt_en": "Same request in two registers: formal to the dean, informal to a classmate.", "tips_ar": ["رسمية: ألقاب وصيغ مهذّبة", "غير رسمية: مباشرة ودافئة", "المحتوى نفسه"], "sample_ar": "(1) سعادة عميد الكلّية حفظه الله، أتقدّم إليكم بطلب تمديد موعد تسليم بحث التخرّج أسبوعين نظرًا لتأخّر وصول البيانات من الجهة الميدانية، وقد أرفقت ما يثبت ذلك. وتفضّلوا بقبول وافر التقدير. (2) هلا سامي، تخيّل، البيانات تأخّرت وما رح ألحق أسلّم البحث. قدّمت طلب تمديد أسبوعين للعميد، ادعُ لي يوافق!", "min_words": 150, "max_words": 220, "time_seconds": 900}'::jsonb, null, null, null),
('AR-SP-B2-001', 'athar-m4a', 'B2', 'speaking', 'صديق عربي يقترح عليك مشروعًا تجاريًّا صغيرًا (مقهى). ردّ عليه بتلقائية: ما يعجبك في الفكرة، ومخاوفك، وأسئلتك قبل أن تقرّر.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B2-01', 'public', '{"genre": "interaction", "prompt_en": "React spontaneously to a friend''s small-business proposal.", "tips_ar": ["تجاوب طبيعي: «فكرة جميلة لكن…»", "مخاوف محدّدة", "أسئلة عملية"], "sample_ar": "والله الفكرة تعجبني خصوصًا الموقع قرب الجامعة، لكن أخاف من المنافسة؛ في الشارع نفسه ثلاثة مقاهٍ. كم رأس المال المطلوب؟ ومن سيدير المكان يوميًّا؟ وهل درست أسعار الإيجار؟ لو أقنعتني بالأرقام فأنا معك.", "min_seconds": 35, "max_seconds": 90, "prep_seconds": 45, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-B2-002', 'athar-m4a', 'B2', 'speaking', 'في مقابلة عمل سُئلت: «حدّثنا عن موقف اختلفت فيه مع زميل وكيف حللته». أجب بطلاقة وثقة.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B2-01', 'professional', '{"genre": "interaction", "prompt_en": "Job interview: describe a disagreement with a colleague and how you resolved it.", "tips_ar": ["الموقف ثم الفعل ثم النتيجة", "نبرة مهنية هادئة", "ما تعلّمته"], "sample_ar": "في مشروع سابق اختلفت مع زميل حول أولويات التسليم؛ كان يريد إطلاق المنتج كاملًا بينما رأيت إطلاق نسخة أوّلية. بدل التصعيد اقترحت أن نعرض الخيارين على العميل بالأرقام، فاختار النسخة الأوّلية. تعلّمت أنّ البيانات تحسم الخلاف أفضل من الجدل.", "min_seconds": 35, "max_seconds": 90, "prep_seconds": 45, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-B2-003', 'athar-m4a', 'B2', 'speaking', 'قدّم عرضًا قصيرًا (90 ثانية) عن تطبيق أو أداة تستعملها وتنصح بها: ما هي، ولمن، وثلاث مزايا، وعيب واحد، ثم أجب عن سؤال متوقّع.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B2-02', 'educational', '{"genre": "presentation", "prompt_en": "Short presentation on an app you recommend; anticipate one question.", "tips_ar": ["افتتاحية جاذبة", "بناء واضح: ما · لمن · لماذا", "توقّع سؤالًا وأجب عنه"], "sample_ar": "هل جرّبتم أن تتعلّموا كلمة جديدة كل يوم دون جهد؟ تطبيق «قاموسي» يفعل ذلك. موجّه للمتعلّمين المتوسّطين. مزاياه: تنبيه يومي ذكي، وأمثلة من نصوص حقيقية، ومراجعة متباعدة. عيبه أنّ النسخة المجّانية محدودة. قد تسألون: هل يدعم اللهجات؟ نعم، في الإصدار الأخير أضيفت الخليجية والمصرية.", "min_seconds": 35, "max_seconds": 90, "prep_seconds": 45, "retakes": 1}'::jsonb, '/miaar/img/phone.svg', 'phone', '{"image": "/miaar/img/phone.svg", "alt": "phone"}'::jsonb),
('AR-SP-B2-004', 'athar-m4a', 'B2', 'speaking', 'اعرض على فريقك نتائج مشروع (افترضها): الهدف، ما تحقّق بالأرقام، ما لم يتحقّق ولماذا، والخطوة التالية.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B2-02', 'professional', '{"genre": "presentation", "prompt_en": "Present project results to your team.", "tips_ar": ["أرقام محدّدة", "صراحة في ما لم يتحقّق", "خطوة تالية واضحة"], "sample_ar": "كان هدفنا رفع رضا العملاء إلى 85% خلال ربع سنة. وصلنا إلى 81%، أي تحسّن بثماني نقاط، بفضل تقليص زمن الردّ إلى أقلّ من ساعتين. لم نبلغ الهدف لأنّ شكاوى التوصيل ما زالت مرتفعة في المناطق البعيدة. الخطوة التالية: التعاقد مع شركة توصيل إقليمية وقياس الأثر خلال شهرين.", "min_seconds": 35, "max_seconds": 90, "prep_seconds": 45, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-B2-005', 'athar-m4a', 'B2', 'speaking', 'ناقش: «هل ينبغي منع السيارات من وسط المدينة؟» اعرض وجهتي النظر بإنصاف ثم موقفك المسبَّب.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B2-03', 'public', '{"genre": "debate", "prompt_en": "Discuss banning cars from the city centre: both sides, then your position.", "tips_ar": ["«يرى المؤيّدون… بينما…»", "إنصاف للطرفين", "موقفك بسبب"], "sample_ar": "يرى المؤيّدون أنّ منع السيارات يقلّل التلوّث ويعيد الشوارع للمشاة والتجارة الصغيرة، كما حدث في مدن أوروبية. بينما يحذّر المعارضون من تضرّر أصحاب المحلّات وكبار السنّ ومن ضعف النقل العام. وأنا أميل إلى المنع التدريجي: البدء بعطلة نهاية الأسبوع مع تحسين الحافلات، ثم التوسّع إذا نجحت التجربة.", "min_seconds": 35, "max_seconds": 90, "prep_seconds": 45, "retakes": 1}'::jsonb, '/miaar/img/car.svg', 'car', '{"image": "/miaar/img/car.svg", "alt": "car"}'::jsonb),
('AR-SP-B2-006', 'athar-m4a', 'B2', 'speaking', 'ناقش قضية «الذكاء الاصطناعي في التعليم»: الفرص، المخاطر، وكيف توازن بينهما لو كنت مديرًا لمدرسة.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-B2-03', 'educational', '{"genre": "debate", "prompt_en": "Discuss AI in education: opportunities, risks, and your balance as a school head.", "tips_ar": ["فرص ثم مخاطر", "أمثلة ملموسة", "قرارك كمدير"], "sample_ar": "الذكاء الاصطناعي يتيح تعليمًا يناسب كل طالب ويوفّر وقت المعلّم في التصحيح. في المقابل يهدّد بالاعتماد الكلّي والغشّ وتسريب بيانات الطلّاب. لو كنت مديرًا لسمحت به في البحث والتدريب على المهارات، ومنعته في التقويم النهائي، ودرّبت المعلّمين أوّلًا قبل الطلّاب.", "min_seconds": 35, "max_seconds": 90, "prep_seconds": 45, "retakes": 1}'::jsonb, null, null, null),
('AR-WR-C1-001', 'athar-m4a', 'C1', 'writing', 'اكتب مقالًا تحليليًّا: «العمل عن بُعد: تحرير للإنسان أم تمدّد للعمل إلى كلّ حياته؟» حلّل الظاهرة من زاويتين على الأقل (اقتصادية، اجتماعية، نفسية…) مع بناء محكم وخاتمة تتجاوز التلخيص.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C1-01', 'educational', '{"genre": "essay", "prompt_en": "Analytical essay on remote work from at least two angles.", "tips_ar": ["أطروحة دقيقة لا عامّة", "انتقال سلس بين الزوايا", "خاتمة تفتح أفقًا"], "sample_ar": "مخطّط نموذجي: مدخل يضع المفارقة؛ زاوية اقتصادية (إنتاجية مقابل كلفة خفيّة)؛ زاوية اجتماعية (الأسرة والعزلة المهنية)؛ زاوية نفسية (محو الحدود وإرهاق الاتّصال)؛ خاتمة تقترح أنّ السؤال ليس «أين نعمل» بل «من يملك الوقت».", "min_words": 220, "max_words": 300, "time_seconds": 1080}'::jsonb, null, null, null),
('AR-WR-C1-002', 'athar-m4a', 'C1', 'writing', 'اكتب مقترحًا مهنيًّا (مذكّرة) لإدارة مؤسّستك لإطلاق برنامج تطوّع للموظّفين: المبرّرات، الأهداف القابلة للقياس، خطّة التنفيذ على مراحل، المخاطر وكيفية إدارتها.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C1-01', 'professional', '{"genre": "proposal", "prompt_en": "Professional proposal memo for an employee volunteering programme.", "tips_ar": ["عناوين ومنطق تدرّجي", "أهداف قابلة للقياس", "مخاطر واقعية وحلولها"], "sample_ar": "مخطّط نموذجي: الخلفية والمبرّر (سمعة المؤسّسة وانتماء الموظّفين)؛ أهداف: 40% مشاركة في السنة الأولى، 1000 ساعة تطوّع؛ مراحل: تجريبية بإدارتين → تعميم → شراكات؛ مخاطر: تعارض مع ضغط العمل، تفاوت الحماس — حلول: يوم مدفوع سنويًّا، اعتراف علني.", "min_words": 220, "max_words": 300, "time_seconds": 1080}'::jsonb, null, null, null),
('AR-WR-C1-003', 'athar-m4a', 'C1', 'writing', 'اكتب مراجعة نقدية لكتاب أو فيلم أثّر فيك: أبرز نقاط قوّته وضعفه بتفصيل مدعوم، وبيّن لمن توصي به ولماذا، متجنّبًا السرد الطويل للأحداث.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C1-02', 'public', '{"genre": "review", "prompt_en": "Critical review of a book or film with supported strengths and weaknesses.", "tips_ar": ["لا تلخّص الحبكة", "نقطة قوّة وضعف مع أمثلة", "توصية موجّهة"], "sample_ar": "مخطّط نموذجي: جملة افتتاحية تحمل الحكم؛ ما يُحسب للعمل (بناء الشخصيات، اللغة) مع شاهد؛ ما يُؤخذ عليه (الإيقاع في الثلث الأخير) مع شاهد؛ موقع العمل بين أعمال مشابهة؛ توصية: لمن يحبّ… وليس لمن يبحث عن…", "min_words": 220, "max_words": 300, "time_seconds": 1080}'::jsonb, null, null, null),
('AR-WR-C1-004', 'athar-m4a', 'C1', 'writing', 'لخّص لصانع قرار نتائج دراسة (افترضها) عن أثر الدوام المرن على الإنتاجية: أبرز الاستنتاجات الجوهرية، وما يدعمها، وحدود الدراسة، وتوصية واحدة حاسمة — في صفحة تنفيذية واحدة.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C1-02', 'professional', '{"genre": "report", "prompt_en": "One-page executive brief on a flexible-hours study.", "tips_ar": ["الاستنتاج الأهمّ أوّلًا", "حدود الدراسة بصراحة", "توصية واحدة"], "sample_ar": "مخطّط نموذجي: الخلاصة في سطرين؛ ثلاث نتائج مرقّمة مع الأرقام؛ حدود (عيّنة قطاع واحد، ستّة أشهر)؛ التوصية: تعميم تدريجي مع مؤشّر قياس ربع سنوي.", "min_words": 220, "max_words": 300, "time_seconds": 1080}'::jsonb, null, null, null),
('AR-WR-C1-005', 'athar-m4a', 'C1', 'writing', 'اكتب النصّ نفسه لقارئَين مختلفَين: (1) شرح مبسّط لطلّاب المرحلة المتوسّطة عن «لماذا ترتفع الأسعار؟» (2) ثمّ الفكرة نفسها في فقرة لصحيفة اقتصادية. أظهر تحكّمك في المفردات والنبرة والتراكيب.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C1-03', 'public', '{"genre": "adapt", "prompt_en": "Explain inflation twice: for teenagers, then for a financial newspaper.", "tips_ar": ["المفردات تتبدّل، الفكرة تثبت", "أمثلة محسوسة للصغار", "مصطلحات دقيقة للصحيفة"], "sample_ar": "مخطّط نموذجي: (1) «تخيّل أنّ في السوق خمس تفّاحات وعشرة أطفال يريدونها…» (2) «يعكس التضخّم الراهن اختلالًا بين الطلب الكلّي المدعوم بالسيولة والعرض المقيَّد بسلاسل الإمداد…».", "min_words": 220, "max_words": 300, "time_seconds": 1080}'::jsonb, null, null, null),
('AR-WR-C1-006', 'athar-m4a', 'C1', 'writing', 'وصلك بريد غاضب من عميل مهمّ بسبب خطأ من فريقك. اكتب ردًّا يحتوي الغضب، ويعترف بالخطأ دون إضعاف موقف المؤسّسة، ويقدّم تعويضًا ومسارًا واضحًا — بأسلوب يوازن بين الدفء والمهنية.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C1-03', 'professional', '{"genre": "adapt", "prompt_en": "Reply to an angry key client: contain, own the error, offer a remedy.", "tips_ar": ["اعتراف صريح بلا تبرير مفرط", "نبرة دافئة مهنية", "خطوات بتواريخ"], "sample_ar": "مخطّط نموذجي: تقدير لصراحته؛ اعتراف محدّد بما حدث؛ ما فعلناه خلال 24 ساعة؛ التعويض؛ نقطة اتّصال مباشرة؛ ختام يعيد الثقة دون مبالغة.", "min_words": 220, "max_words": 300, "time_seconds": 1080}'::jsonb, null, null, null),
('AR-SP-C1-001', 'athar-m4a', 'C1', 'speaking', 'تحدّث بطلاقة لمدّة 90 ثانية عن «لحظة غيّرت نظرتك إلى العمل أو التعلّم»: ابنِ الحديث بتدرّج، واستعمل تعابير دقيقة لنقل المشاعر والأفكار دون تردّد ظاهر.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C1-01', 'public', '{"genre": "fluent_talk", "prompt_en": "Fluent 90-second talk on a moment that changed your view of work or learning.", "tips_ar": ["افتتاحية قوية", "تعابير دقيقة", "خاتمة تربط الماضي بالحاضر"], "sample_ar": "مخطّط نموذجي: مشهد افتتاحي؛ ما كنت أظنّ؛ اللحظة؛ التحوّل في التفكير؛ أثرها اليوم.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C1-002', 'athar-m4a', 'C1', 'speaking', 'موضوع مفاجئ: «الصمت». تحدّث فورًا دون تحضير طويل، مستعملًا أمثلة وتشبيهات، مع الحفاظ على التدفّق والترابط.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C1-01', 'personal', '{"genre": "fluent_talk", "prompt_en": "Spontaneous fluent talk: silence.", "tips_ar": ["لا تخف من الاستطراد المضبوط", "تشبيه أو مثال", "عُد إلى الفكرة الأم"], "sample_ar": "مخطّط نموذجي: الصمت كلغة؛ الصمت في الحوار الحديث؛ تجربة شخصية؛ ما يعلّمنا.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C1-003', 'athar-m4a', 'C1', 'speaking', 'أنت في اجتماع مهني تعترض فيه على قرار مديرك بأدب وحزم: اعرض اعتراضك بالأدلّة، واستبق الاعتراضات، واقترح بديلًا، بلغة مرنة تناسب السياق الرسمي.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C1-02', 'professional', '{"genre": "professional_setting", "prompt_en": "Object to a manager''s decision in a meeting: evidence, anticipation, alternative.", "tips_ar": ["«مع تقديري لـ… إلا أنّ…»", "أدلّة محدّدة", "بديل لا رفض فقط"], "sample_ar": "مخطّط نموذجي: تقدير؛ الاعتراض بدليلين؛ ما قد يُقال ردًّا وجوابه؛ البديل بخطّة زمنية؛ طلب وقت للتجربة.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C1-004', 'athar-m4a', 'C1', 'speaking', 'في ندوة أكاديمية، علّق على بحث سمعته (افترضه): لخّص فكرته في جملتين، أثنِ على ما يستحقّ، ثمّ اطرح نقدين منهجيَّين وسؤالًا للباحث.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C1-02', 'educational', '{"genre": "professional_setting", "prompt_en": "Academic seminar: comment on a paper — summary, merit, two methodological critiques, a question.", "tips_ar": ["تلخيص أمين", "نقد منهجي لا شخصي", "سؤال مفتوح"], "sample_ar": "مخطّط نموذجي: تلخيص؛ ما يميّز البحث؛ نقد العيّنة؛ نقد أداة القياس؛ سؤال عن قابلية التعميم.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C1-005', 'athar-m4a', 'C1', 'speaking', 'اعرض موضوعًا معقّدًا لجمهور غير متخصّص: «كيف تعمل اللقاحات؟» أو «ما سلاسل الإمداد؟» — بسّط دون تسطيح، واربط الأجزاء، واختم بخاتمة تجيب عن «وما شأني أنا؟».', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C1-03', 'public', '{"genre": "complex_presentation", "prompt_en": "Explain a complex topic to a lay audience with a \"so what\" ending.", "tips_ar": ["استعارة مركزية", "انتقالات واضحة", "خاتمة شخصية للمستمع"], "sample_ar": "مخطّط نموذجي: استعارة (تدريب الجيش قبل المعركة)؛ ثلاث خطوات؛ الأخطاء الشائعة؛ «ما شأنك أنت».", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C1-006', 'athar-m4a', 'C1', 'speaking', 'قدّم تحليلًا لمشكلة متعدّدة الأسباب في مؤسّستك (افترضها: تسرّب الموظّفين الجدد): الأسباب المتشابكة، أولويّاتها، وخطّة معالجة بخاتمة مناسبة.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C1-03', 'professional', '{"genre": "complex_presentation", "prompt_en": "Present a multi-cause organisational problem with a prioritised plan.", "tips_ar": ["أسباب مترابطة لا قائمة", "ترتيب بالأولوية", "خاتمة بما يتغيّر خلال سنة"], "sample_ar": "مخطّط نموذجي: الأرقام؛ ثلاثة أسباب وتفاعلها؛ الأولوية بحسب الأثر والكلفة؛ خطّة 90 يومًا؛ ما سيختلف بعد سنة.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-WR-C2-001', 'athar-m4a', 'C2', 'writing', 'اكتب مقالًا فكريًّا في موضوع «الذاكرة في زمن التخزين اللامحدود»: ابنِ حجّة مركّبة، ووظّف الاستشهاد والمفارقة والتدرّج البلاغي، بأسلوب سلس لا يُحسّ فيه الجهد.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C2-01', 'public', '{"genre": "essay", "prompt_en": "Intellectual essay: memory in the age of unlimited storage.", "tips_ar": ["بناء منطقي متصاعد", "أدوات بلاغية بلا تكلّف", "انتقالات غير مرئية"], "sample_ar": "مخطّط نموذجي: مفارقة الافتتاح (نحفظ كلّ شيء ولا نتذكّر شيئًا)؛ الذاكرة كاختيار؛ التخزين كإلغاء للاختيار؛ شواهد؛ استدراك؛ خاتمة تعيد المفارقة مقلوبة.", "min_words": 280, "max_words": 380, "time_seconds": 1200}'::jsonb, null, null, null),
('AR-WR-C2-002', 'athar-m4a', 'C2', 'writing', 'اكتب ورقة موقف لمؤسّسة ثقافية حول «اللغة العربية والمنصّات الرقمية»: تشخيص دقيق، موقف واضح، سياسات مقترحة، وردّ استباقي على الاعتراضات، بلغة مؤسّسية رفيعة.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C2-01', 'professional', '{"genre": "position_paper", "prompt_en": "Position paper: Arabic and digital platforms.", "tips_ar": ["تشخيص بأدلّة", "سياسات محدّدة", "ردّ استباقي"], "sample_ar": "مخطّط نموذجي: الموجز التنفيذي؛ التشخيص (المحتوى، الأدوات، التعليم)؛ الموقف؛ ثلاث سياسات؛ الاعتراضات وردّها؛ خاتمة.", "min_words": 280, "max_words": 380, "time_seconds": 1200}'::jsonb, null, null, null),
('AR-WR-C2-003', 'athar-m4a', 'C2', 'writing', 'اكتب نقدًا أدبيًّا لقصيدة أو قصّة قصيرة تعرفها: حلّل البنية والصور والإيقاع، وناقش قراءة شائعة لها وقدّم قراءتك المغايرة بشواهد.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C2-02', 'educational', '{"genre": "critique", "prompt_en": "Literary critique of a poem or short story with an alternative reading.", "tips_ar": ["تحليل لا انطباع", "قراءة شائعة ثم مغايرة", "شواهد نصّية"], "sample_ar": "مخطّط نموذجي: موقع النصّ؛ البنية؛ الصورة المحورية؛ القراءة الشائعة؛ قراءتك وشواهدها؛ ما يفتحه ذلك.", "min_words": 280, "max_words": 380, "time_seconds": 1200}'::jsonb, null, null, null),
('AR-WR-C2-004', 'athar-m4a', 'C2', 'writing', 'اكتب مراجعة مهنية ناقدة لتقرير استراتيجي صادر عن جهة (افترضه): اختبر منطقه الداخلي، واتّساق أرقامه، وافتراضاته غير المعلنة، واقترح ما كان ينبغي أن يُسأل.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C2-02', 'professional', '{"genre": "critique", "prompt_en": "Critical professional review of a strategic report.", "tips_ar": ["الافتراضات غير المعلنة", "اتّساق داخلي", "الأسئلة الغائبة"], "sample_ar": "مخطّط نموذجي: ما يدّعيه التقرير؛ فجوات المنطق؛ تناقض الأرقام؛ الافتراضات؛ الأسئلة الغائبة؛ حكم ختامي متوازن.", "min_words": 280, "max_words": 380, "time_seconds": 1200}'::jsonb, null, null, null),
('AR-WR-C2-005', 'athar-m4a', 'C2', 'writing', 'أعد كتابة فقرة إخبارية جافّة (افترضها عن افتتاح مكتبة عامّة) ثلاث مرّات: بأسلوب ساخر، ثمّ بأسلوب شاعري، ثمّ بأسلوب قانوني — مع الحفاظ على الوقائع كلّها.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C2-03', 'public', '{"genre": "style", "prompt_en": "Rewrite a dry news paragraph in satirical, poetic, and legal styles.", "tips_ar": ["الوقائع ثابتة", "كلّ أسلوب بأدواته", "لا مبالغة تُفسد الأسلوب"], "sample_ar": "مخطّط نموذجي: الساخر (المفارقة والتصغير)؛ الشاعري (الإيقاع والصورة)؛ القانوني (التعريفات والبنود والإحالات).", "min_words": 280, "max_words": 380, "time_seconds": 1200}'::jsonb, null, null, null),
('AR-WR-C2-006', 'athar-m4a', 'C2', 'writing', 'اكتب كلمة افتتاحية لحفل تخرّج (250–350 كلمة) توازن بين الوقار والدفء، وتوظّف الإيقاع والتكرار البلاغي والاقتباس المناسب، وتختم بجملة تبقى في الذاكرة.', '[]'::jsonb, 'in_review', 'manual', 'writing_task', 'WR-C2-03', 'professional', '{"genre": "style", "prompt_en": "Graduation address balancing gravitas and warmth.", "tips_ar": ["إيقاع الجمل", "تكرار بلاغي مقصود", "جملة ختامية خالدة"], "sample_ar": "مخطّط نموذجي: مدخل شخصي؛ ثلاثية بلاغية؛ اقتباس؛ الالتفات إلى الأهل؛ الجملة الأخيرة.", "min_words": 280, "max_words": 380, "time_seconds": 1200}'::jsonb, null, null, null),
('AR-SP-C2-001', 'athar-m4a', 'C2', 'speaking', 'شارك في حديث حرّ: مقدّم برنامج يسألك فجأة عن «أغرب عادة في بلدك وكيف تفسّرها لأجنبي». أجب بعفوية تامّة، موظّفًا التعابير الاصطلاحية والتلوين الأسلوبي والدعابة إن ناسبت.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C2-01', 'public', '{"genre": "effortless", "prompt_en": "Free talk: strangest custom in your country, explained to a foreigner.", "tips_ar": ["عفوية بلا توتّر", "تعابير اصطلاحية", "دعابة محسوبة"], "sample_ar": "مخطّط نموذجي: العادة؛ مشهد؛ التفسير الثقافي؛ ردّ فعل الأجنبي؛ التفاتة ختامية.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C2-002', 'athar-m4a', 'C2', 'speaking', 'أدِر نقاشًا متوتّرًا بين طرفين (افترض الموقف) بوصفك وسيطًا: صِغ موقف كلّ طرف بدقّة، وخفّض التوتّر بلغة مرنة، وانتقل بين السجلّ الرسمي والودّي بسلاسة.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C2-01', 'professional', '{"genre": "effortless", "prompt_en": "Mediate a tense discussion: reframe each side, lower tension, shift register smoothly.", "tips_ar": ["إعادة صياغة أمينة", "تهدئة بلا تسطيح", "انتقال سجلّ واعٍ"], "sample_ar": "مخطّط نموذجي: الاعتراف بالتوتّر؛ موقف أ؛ موقف ب؛ المشترك؛ اقتراح؛ ختام ودّي.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C2-003', 'athar-m4a', 'C2', 'speaking', 'اشرح الفرق الدقيق بين ثلاث كلمات متقاربة (مثل: الحزن والأسى والكآبة، أو الحرّية والانفلات والاستقلال) بأمثلة سياقية، وبيّن متى يُخطئ المتحدّث في اختيارها.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C2-02', 'educational', '{"genre": "nuance", "prompt_en": "Explain fine distinctions between three near-synonyms with contextual examples.", "tips_ar": ["فروق دقيقة لا قواميس", "أمثلة سياقية", "خطأ شائع"], "sample_ar": "مخطّط نموذجي: الكلمة الأولى وسياقها؛ الثانية؛ الثالثة؛ متى تتبادل ومتى لا؛ خطأ شائع.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C2-004', 'athar-m4a', 'C2', 'speaking', 'انقل خبرًا حسّاسًا إلى فريقك (إلغاء مشروع كانوا متحمّسين له) بحيث تنقل الحقيقة كاملة، وتحفظ كرامة الجهد، وتضبط الفروق بين «توقّف» و«تأجيل» و«إلغاء» بدقّة لا تُسيء الفهم.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C2-02', 'professional', '{"genre": "nuance", "prompt_en": "Deliver sensitive news to a team with precise shades of meaning.", "tips_ar": ["دقّة المصطلح", "صدق وتقدير", "لا غموض مريح"], "sample_ar": "مخطّط نموذجي: الحقيقة في الجملة الأولى؛ لماذا؛ ما يعنيه وما لا يعنيه؛ ما التالي؛ شكر محدّد.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C2-005', 'athar-m4a', 'C2', 'speaking', 'تحدّث عن موضوع معقّد (مثل «العدالة بين الأجيال»)، وأثناء حديثك اكتشف أنّك أخطأت في معلومة أو مسار الحجّة، فتدارك وأعد البناء دون أن ينقطع التدفّق أو يشعر المستمع بالارتباك.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C2-03', 'public', '{"genre": "repair", "prompt_en": "Talk on a complex topic, then self-repair and restructure seamlessly.", "tips_ar": ["تدارك غير مرئي", "إعادة بناء الحجّة", "استمرار التدفّق"], "sample_ar": "مخطّط نموذجي: الحجّة؛ «بل الأدقّ أن نقول…»؛ إعادة البناء؛ الخاتمة.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null),
('AR-SP-C2-006', 'athar-m4a', 'C2', 'speaking', 'أجب ارتجالًا عن سؤال صحفي محرج (افترضه) حول قرار اتّخذته مؤسّستك: أعد صياغة السؤال بما يخدمك دون مراوغة، وصحّح فرضيّته الخاطئة بلباقة، وقدّم جوابًا متماسكًا.', '[]'::jsonb, 'in_review', 'manual', 'speaking_task', 'SP-C2-03', 'professional', '{"genre": "repair", "prompt_en": "Answer a hostile press question: reframe, correct the premise, answer coherently.", "tips_ar": ["تصحيح الفرضية بلباقة", "لا مراوغة", "جواب متماسك"], "sample_ar": "مخطّط نموذجي: «أفهم أنّ السؤال يفترض… والواقع…»؛ الجواب؛ ما نفعله؛ جملة ختامية.", "min_seconds": 45, "max_seconds": 90, "prep_seconds": 60, "retakes": 1}'::jsonb, null, null, null)
